// stringUtils.js
export function capitalize(str) { return str.charAt(0).toUpperCase() + str.slice(1); }
export const WERSJA = "1.0.0";
export default function odwroc(str) { return [...str].reverse().join(""); }

// inny-plik.js
import obroc, { capitalize, WERSJA } from "./stringUtils.js";
console.log(obroc("kurs"));       // "sruk"
console.log(capitalize("react")); // "React"
console.log(WERSJA);              // "1.0.0"

// mathUtils.js
export const PI = 3.14159;
export function dodaj(a, b) { return a + b; }
export default function pomnoz(a, b) { return a * b; }

// inny-plik.js
import pomnozAlias, { PI, dodaj } from "./mathUtils.js";
console.log(pomnozAlias(2, 2)); // 4
console.log(dodaj(2, 2));       // 4
console.log(PI);                // 3.14159

// Karta.js
export default class Karta {
  constructor(tytul) {
    this.tytul = tytul;
  }
}
export const ROZMIARY = { maly: "sm", duzy: "lg" };

// inny-plik.js
import Karta, { ROZMIARY } from "./Karta.js";
const karta = new Karta("Pierwsza karta");
console.log(karta.tytul);      // "Pierwsza karta"
console.log(ROZMIARY.duzy);    // "lg"

// mathUtils.js
export const PI = 3.14159;
export function dodaj(a, b) { return a + b; }
export default function pomnoz(a, b) { return a * b; }

// inny-plik.js
import pomnoz, { PI as LiczbaPi, dodaj } from "./mathUtils.js";
console.log(pomnoz(3, 3)); // 9
console.log(LiczbaPi);     // 3.14159
console.log(dodaj(1, 1));  // 2

// Card.jsx eksportuje:
// export default function Card() {...}
// export const CARD_VARIANTS = { outlined: 'outlined', filled: 'filled' };

// App.jsx - import wygladalby dokladnie tak:
// import Card, { CARD_VARIANTS } from './Card.jsx';
// dokladnie ta sama skladnia, ktorej uzylismy dla mathUtils.js i stringUtils.js -
// tylko zamiast funkcji matematycznych/tekstowych, importujemy komponent React
// razem z powiazana ze stala.

// Skladnia laczonego importu WYMAGA, aby import domyslny (bez klamer)
// wystepowal ZAWSZE jako PIERWSZY, przed przecinkiem i klamrami z
// nazwanymi eksportami. To ustalona regula skladni jezyka JavaScript -
// nie mozna jej odwrocic.
//
// Probujac napisac: import { capitalize }, odwroc from './stringUtils.js';
// -- otrzymalibysmy SyntaxError - silnik JS oczekuje, ze pierwsza czesc
// (przed przecinkiem, bez klamer) to zawsze import domyslny, a nastepna
// czesc (w klamrach) to importy nazwane. Odwrocona kolejnosc lamie te
// regule skladniowa i uniemozliwia poprawne sparsowanie instrukcji import.

